{"operation": "bash", "command": "cd /exercise && cat <<'EOF' > book-store.js
const BOOK_PRICE_IN_CENTS = 800;

// Price of buying the indicated number of different books together.
const GROUP_PRICES_IN_CENTS = [
  0,
  BOOK_PRICE_IN_CENTS,
  1520,
  2160,
  2560,
  3000,
];

// `counts` is always sorted from the most-copied title to the least-copied one.
// Because titles are interchangeable, an optimal group can always be formed
// from the titles with the most copies remaining.
const cheapestRemaining = (counts, memo) => {
  const key = counts.join(',');
  if (memo.has(key)) {
    return memo.get(key);
  }

  const differentTitles = counts.filter((count) => count > 0).length;
  if (differentTitles === 0) {
    memo.set(key, 0);
    return 0;
  }

  let cheapest = Infinity;

  for (let size = 1; size <= differentTitles; size += 1) {
    const remaining = counts.slice();

    for (let index = 0; index < size; index += 1) {
      remaining[index] -= 1;
    }

    remaining.sort((left, right) => right - left);

    const price = GROUP_PRICES_IN_CENTS[size] +
      cheapestRemaining(remaining, memo);

    if (price < cheapest) {
      cheapest = price;
    }
  }

  memo.set(key, cheapest);
  return cheapest;
};

export const cost = (books) => {
  const countsByTitle = new Map();

  for (const book of books) {
    countsByTitle.set(book, (countsByTitle.get(book) || 0) + 1);
  }

  const counts = Array.from(countsByTitle.values())
    .sort((left, right) => right - left);

  return cheapestRemaining(counts, new Map());
};
