from functools import lru_cache
price = (0, 800, 1520, 2160, 2560, 3000)

@lru_cache(None)
def topk(c):
    if not any(c):
        return 0
    m = sum(v > 0 for v in c)
    best = None
    for k in range(1, m + 1):
        nxt = list(c)
        for i in range(k):
            nxt[i] -= 1
        cand = price[k] + topk(tuple(sorted(nxt, reverse=True)))
        if best is None or cand < best:
            best = cand
    return best

@lru_cache(None)
def exhaustive(c):
    if not any(c):
        return 0
    best = None
    for mask in range(1, 1 << 5):
        if any((mask >> i) & 1 and c[i] == 0 for i in range(5)):
            continue
        k = mask.bit_count()
        nxt = list(c)
        for i in range(5):
            if (mask >> i) & 1:
                nxt[i] -= 1
        cand = price[k] + exhaustive(tuple(sorted(nxt, reverse=True)))
        if best is None or cand < best:
            best = cand
    return best

def states(n):
    for a in range(n + 1):
        for b in range(a + 1):
            for c in range(b + 1):
                for d in range(c + 1):
                    for e in range(d + 1):
                        yield (a, b, c, d, e)

for n in (10, 16):
    mismatches = []
    for s in states(n):
        if topk(s) != exhaustive(s):
            mismatches.append((s, topk(s), exhaustive(s)))
            if len(mismatches) == 10:
                break
    print('max count', n, 'mismatches', mismatches)
