const fs = require('fs');
const babel = require('/npm-install/node_modules/@babel/core');

const source = fs.readFileSync('/exercise/book-store.js', 'utf8');
const transformed = babel.transformSync(source, {
  filename: '/exercise/book-store.js',
  babelrc: false,
  configFile: false,
  presets: [[require('/npm-install/node_modules/@babel/preset-env'), {
    targets: { node: 'current' },
  }]],
}).code;

const loaded = { exports: {} };
new Function('module', 'exports', 'require', transformed)(
  loaded,
  loaded.exports,
  require,
);
const { cost } = loaded.exports;

const prices = [0, 800, 1520, 2160, 2560, 3000];
const exhaustiveMemo = new Map();

function exhaustive(counts) {
  const key = counts.join(',');
  if (exhaustiveMemo.has(key)) return exhaustiveMemo.get(key);
  if (counts.every((count) => count === 0)) return 0;

  let best = Infinity;
  for (let mask = 1; mask < 32; mask += 1) {
    const remaining = counts.slice();
    let size = 0;
    let valid = true;

    for (let i = 0; i < 5; i += 1) {
      if ((mask & (1 << i)) !== 0) {
        size += 1;
        if (remaining[i] === 0) valid = false;
        else remaining[i] -= 1;
      }
    }

    if (valid) {
      remaining.sort((a, b) => b - a);
      best = Math.min(best, prices[size] + exhaustive(remaining));
    }
  }

  exhaustiveMemo.set(key, best);
  return best;
}

function expand(counts) {
  const basket = [];
  counts.forEach((count, title) => {
    for (let i = 0; i < count; i += 1) basket.push(title + 1);
  });
  return basket;
}

let checked = 0;
let mismatches = 0;
const limit = 12;

for (let a = 0; a <= limit; a += 1) {
  for (let b = 0; b <= a; b += 1) {
    for (let c = 0; c <= b; c += 1) {
      for (let d = 0; d <= c; d += 1) {
        for (let e = 0; e <= d; e += 1) {
          const counts = [a, b, c, d, e];
          const expected = exhaustive(counts.slice().sort((x, y) => y - x));
          const actual = cost(expand(counts));
          checked += 1;
          if (actual !== expected) {
            mismatches += 1;
            if (mismatches <= 10) {
              console.error('MISMATCH', counts, { actual, expected });
            }
          }
        }
      }
    }
  }
}

const spotChecks = [
  { basket: [], expected: 0 },
  { basket: ['A', 'B', 'A', 'B'], expected: 1520 },
  { basket: ['A', 'B', 'C', 'D', 'E', 'A', 'B', 'C'], expected: 5120 },
  { basket: [5, 4, 3, 2, 1, 5, 4, 3, 2, 1], expected: 6000 },
];

let spotFailures = 0;
for (const { basket, expected } of spotChecks) {
  const actual = cost(basket);
  if (actual !== expected) {
    spotFailures += 1;
    console.error('SPOT FAILURE', basket, { actual, expected });
  }
}

console.log(JSON.stringify({
  exhaustiveVectorsChecked: checked,
  exhaustiveMismatches: mismatches,
  spotChecks: spotChecks.length,
  spotFailures,
}));

if (mismatches > 0 || spotFailures > 0) process.exit(1);
